            headers.push(`Cc: ${options.cc.join(', ')}`);
        if (options.bcc?.length)
            headers.push(`Bcc: ${options.bcc.join(', ')}`);
        if (options.inReplyTo)
            headers.push(`In-Reply-To: ${options.inReplyTo}`);
